import{_ as s}from"./chunks/architecture.Cs8uKTTN.js";import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/overview.md","filePath":"concepts/overview.md","lastUpdated":1784564572000}'),o={name:"concepts/overview.md"};function p(c,e,r,l,h,d){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>swag2mcp acts as a bridge between API specifications and LLM agents:</p><img src="'+s+`" width="800" alt="swag2mcp architecture"><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><p><strong>Spec</strong> — a logical container representing an API domain or service (e.g., YouTube, Binance, Open-Meteo). Each spec has a unique <code>domain</code>, a <code>base_url</code>, optional <code>auth</code>, and contains one or more collections. You can also set <code>llm_instruction</code> — a short hint injected into the swag2mcp system prompt that tells the LLM what this spec is for and when to use it. Learn more: <a href="./specs">Specs</a>.</p><p><strong>Collection</strong> — a single OpenAPI/Swagger/Postman file describing a specific API. It points to a <code>location</code> (URL or local file path). One spec can have multiple collections — for example, the &quot;meteo&quot; spec might have &quot;Forecast&quot;, &quot;Air Quality&quot;, and &quot;Marine&quot; collections, each pointing to a different spec file. Learn more: <a href="./collections">Collections</a>.</p><p><strong>Tag</strong> — a category of endpoints inside a collection. Helps the LLM find the right operations more precisely. Learn more: <a href="./tags">Tags</a>.</p><p><strong>Endpoint</strong> — a specific HTTP method + path (e.g., <code>GET /api/users</code>). The LLM can find an endpoint by description, inspect its parameters and schemas, and then invoke it. Learn more: <a href="./endpoints">Endpoints</a>.</p><p><strong>Workspace</strong> — the directory where swag2mcp stores config, spec cache, saved responses, and auth scripts. Learn more: <a href="./workspace">Workspace</a>.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><p><strong>Add a spec or collection</strong> — define it in the YAML config (<code>~/.swag2mcp/swag2mcp.yaml</code>). For example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp parses each collection</strong> — creates Tags and Endpoints, indexes them for search.</p></li><li><p><strong>LLM finds the right endpoint</strong> — through MCP tools (<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>) the LLM searches for a matching endpoint by description, reviews its parameters and request schema.</p></li><li><p><strong>LLM invokes the endpoint</strong> — via the MCP tool <code>invoke</code>, the LLM sends the request. swag2mcp validates every input parameter against the endpoint&#39;s OpenAPI schema (path params, query params, headers, request body) before making the call. If something doesn&#39;t match the schema, the LLM gets a clear error explaining what&#39;s wrong. Once validated, swag2mcp executes the real HTTP call and returns the result.</p></li><li><p><strong>Result goes back to the LLM</strong> — the API response is passed back to the agent. Large responses are saved to the workspace and can be explored with three dedicated MCP tools: <code>response_outline</code> (see the structure), <code>response_compress</code> (shrink to a representative sample), and <code>response_slice</code> (extract specific fragments).</p></li></ol><p>swag2mcp is a bridge between LLMs and the world of APIs. You add API specifications, and the LLM — through the MCP protocol — finds the right endpoints, inspects their documentation, and calls them. All you need to do is add a spec and start the MCP server.</p><blockquote><p><strong>Config is editable at any time.</strong> The YAML config file (<code>~/.swag2mcp/swag2mcp.yaml</code>) can be edited by hand — add specs, change auth, tweak settings. After every edit, restart the MCP server (<code>swag2mcp mcp</code>) for changes to take effect.</p></blockquote><h2 id="hierarchy" tabindex="-1">Hierarchy <a class="header-anchor" href="#hierarchy" aria-label="Permalink to &quot;Hierarchy&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, e.g. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection 1 (spec file, e.g. forecast.yml)</span></span>
<span class="line"><span>        └── Tag 1 (category)</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpoint (POST /api/forecast)</span></span>
<span class="line"><span>        └── Tag 2</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (spec file, e.g. air-quality.yml)</span></span>
<span class="line"><span>        └── Tag 3</span></span>
<span class="line"><span>              └── Endpoint (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const u=a(o,[["render",p]]);export{m as __pageData,u as default};
